const callFunctionalLocationsApi = async () => {
  const cachedOptions = localStorage.getItem('functionalLocationOptions');
  if (cachedOptions) {
    component.data.values = JSON.parse(cachedOptions); // Use cached options
    console.log('Using cached functionalLocationOptions');
    return JSON.parse(cachedOptions);
  }
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }

  // Get 'eventIds' from the URL parameters
  const urlParams = new URLSearchParams(window.location.search);
  const eventIds = urlParams.get('eventIds');

  if (!eventIds) {
    console.error('eventIds parameter not found in the URL');
    return;
  }

  const baseUrl = window.location.hostname.includes('localhost')
    ? 'http://localhost:8081'
    : localStorage.getItem('baseUrl') || '';

  try {
    // First API call to get the fault history with eventIds
    const faultHistoryResponse = await fetch(`${baseUrl}/case-definition/fault-history/eventIds?eventIds=${encodeURIComponent(eventIds)}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!faultHistoryResponse.ok) {
      throw new Error(`Fault history API call failed with status: ${faultHistoryResponse.status}`);
    }

    const faultHistoryData = await faultHistoryResponse.json();
    const assetDisplayName = faultHistoryData[0]?.AssetDisplayName;

    if (!assetDisplayName) {
      console.error('AssetDisplayName not found in the fault history response');
      return;
    }

    // Second API call to get functional locations using AssetDisplayName
    const funcLocationsResponse = await fetch(`${baseUrl}/case-definition/funcational-locations?assetName=${encodeURIComponent(assetDisplayName)}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!funcLocationsResponse.ok) {
      throw new Error(`Functional locations API call failed with status: ${funcLocationsResponse.status}`);
    }

    const funcLocationsData = await funcLocationsResponse.json();
    const locationOptions = funcLocationsData.map(location => ({
      label: location.assetFL, // Display the functional location name
      value: location.assetFL, // Use ID as the unique value
    }));

    return locationOptions;
  } catch (error) {
    console.error('Error calling the APIs:', error);
  }
};

// Example of using the modified callFunctionalLocationsApi function
callFunctionalLocationsApi().then(locationOptions => {
  if (locationOptions) {
    localStorage.setItem('functionalLocationOptions', JSON.stringify(locationOptions));
    component.data.values = locationOptions; // Assign the fetched options to component's data
  }
});

